'use strict';
const groups = [{"id": "centro", "number": "01", "title": "Centro & Santo Domingo", "timing": "LITTLE OUTINGS THROUGHOUT THE TRIP", "color": "pink", "description": "Start close to home. A walk, a church and a long lunch are enough for any one day.", "sections": [["WANDER A LITTLE", [["alcala", "Andador Macedonio Alcalá", "pedestrian street from Santo Domingo to the Zócalo"], ["zocalo", "Zócalo & the Cathedral", "shady main square for people-watching"], ["santodomingo", "Templo de Santo Domingo", "baroque church with a gilded, carved interior"], ["culturas", "Museo de las Culturas de Oaxaca", "regional history in the former convent next door"], ["jardin", "Jardín Etnobotánico", "garden of native plants and cacti", "Guided tours only: check the times."]]], ["EAT & LINGER", [["brujula", "Café Brújula", "local roaster for a slow morning"], ["tlayuda", "A tlayuda", "giant crisp tortilla from a street grill"], ["mayordomo", "Hot chocolate at Mayordomo", "stone-ground chocolate, with pan de yema"], ["mole", "Mole negro at Las Quince Letras", "the dark, chocolatey one Oaxaca is famous for", "From our saved list. Go for a long lunch."]]]], "note": "One main thing and a meal can be plenty."}, {"id": "muertos", "number": "02", "title": "Día de Muertos", "timing": "THE BIG NIGHTS", "color": "blue", "description": "Altars, brass bands and candlelit cemeteries. The reason we’re here at this time.", "sections": [["ALTARS & PARADES", [["abastos", "Mercado de Abastos", "huge market piled with marigolds, sugar skulls and pan de muerto"], ["altars", "Altars around the centre", "public ofrendas in churches, squares and shopfronts"], ["comparsas", "Comparsas", "costumed street parades with brass bands", "Follow the music in the evening."]]], ["THE CEMETERY NIGHT", [["panteon", "Panteón General", "the city cemetery, decorated for the season"], ["xoxo", "Xoxocotlán cemetery vigil", "families keep watch by candlelight at the graves", "About 8 km out: go with an organised shuttle or tour."]]]], "note": "The cemetery nights are 1 and 2 November. Keep the day after completely free."}, {"id": "markets", "number": "03", "title": "Markets & Jalatlaco", "timing": "TWO RELAXED AFTERNOONS", "color": "green", "description": "Smoke, chocolate and cobbled lanes. Come hungry.", "sections": [["ONE AFTERNOON", [["veinte", "Mercado 20 de Noviembre", "the Pasillo de Humo: pick your meat and they grill it"], ["juarezmkt", "Mercado Benito Juárez", "chocolate, cheese, mezcal and chapulines"]]], ["ANOTHER AFTERNOON", [["jalatlaco", "Barrio de Jalatlaco", "cobbled lanes, murals and small cafés"], ["mezcaloteca", "Mezcaloteca", "guided tasting of small-batch mezcals", "Book ahead."], ["fortin", "Cerro del Fortín", "hill above the city for sunset"]]]], "note": "Markets are busiest at lunchtime, which is exactly the point."}, {"id": "cooking", "number": "04", "title": "A cooking class", "timing": "ONE MORNING", "color": "yellow", "description": "Shop the market with a cook, then make it all from scratch.", "sections": [["MARKET TO TABLE", [["class", "Market visit & cooking class", "salsas, tortillas and a mole", "Book ahead."]]]], "note": "Lunch is whatever you cook, so skip breakfast."}, {"id": "food", "number": "05", "title": "Food & drinks", "timing": "FROM OUR SAVED LIST", "color": "green", "description": "The places we pinned before we left. One a day is plenty.", "sections": [["BREAKFAST & BREAD", [["boulenc", "Boulenc", "bakery and brunch in Jalatlaco"], ["bodaega", "Bodæga", "small artisan bakery on Hidalgo"]]], ["LONG LUNCHES, LATE SUPPERS", [["levadura", "Levadura de Olla", "Thalía Barrios’s home-style Oaxacan cooking", "Book ahead."], ["humo", "La Cocina de Humo", "her tasting menu cooked over a wood fire", "Book well ahead."], ["danzantes", "Los Danzantes", "contemporary Oaxacan food in an open courtyard"], ["tierrasol", "Tierra del Sol", "Mixtec cooking on a rooftop"], ["copal", "Copal", "restaurant on Alcalá, above Santo Domingo"]]], ["A DRINK IN THE EVENING", [["selva", "Selva", "cocktails made with Oaxacan ingredients"]]]], "note": "Pair a dinner with whatever walk is nearby."}, {"id": "montealban", "number": "★", "title": "Monte Albán", "timing": "A HALF-DAY TRIP", "color": "yellow", "description": "A Zapotec city on a flattened hilltop above the valley.", "sections": [["A MORNING OUT", [["alban", "Monte Albán", "ruins, plazas and wide valley views", "Go early: there’s very little shade."], ["arrazola", "San Antonio Arrazola", "nearby village of painted wooden alebrijes"]]]], "note": "Back in town for a late lunch.", "weekend": true}, {"id": "hierve", "number": "★", "title": "Hierve el Agua & Mitla", "timing": "A FULL-DAY TRIP", "color": "blue", "description": "Petrified waterfalls, carved ruins and a mezcal distillery, with a tour or a driver.", "sections": [["THE WHOLE DAY, TAKEN SLOWLY", [["tule", "Árbol del Tule", "one of the widest trees in the world"], ["mitla", "Mitla", "ruins covered in stone fretwork"], ["palenque", "A mezcal palenque", "family distillery around Santiago Matatlán"], ["hierve", "Hierve el Agua", "petrified waterfalls and clifftop mineral pools", "It sometimes closes without warning: check the week before."]]]], "note": "A long day. Keep the next one empty.", "weekend": true}, {"id": "tlacolula", "number": "+", "title": "Tlacolula & Teotitlán", "timing": "A SUNDAY OUTING", "color": "pink", "description": "The big Sunday market, then a weaving village down the road.", "sections": [["ON A SUNDAY", [["tlacolula", "Tlacolula market", "one of the biggest weekly markets in the valley", "Sundays only."], ["barbacoa", "Barbacoa for lunch", "slow-cooked goat or lamb at the market"], ["teotitlan", "Teotitlán del Valle", "rugs made on wooden looms"]]]], "note": "Bring cash."}];
const optional = [["tilcajete", "San Martín Tilcajete", "another alebrije village, south of the city"], ["temazcal", "A temazcal", "traditional steam bath, for a rainy afternoon"], ["tejate", "Tejate", "cold maize and cacao drink from the markets"], ["chapulines", "Chapulines", "toasted grasshoppers with lime and chilli, if brave"]];
const KEY='frolicking-nicky-oaxaca-v2';
let checked={}; let storageOK=true;
try { const saved=JSON.parse(localStorage.getItem(KEY)||'{}'); if(saved && typeof saved==='object' && !Array.isArray(saved)) checked=saved; } catch {storageOK=false;}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function item(row,extra=false) {const [id,title,desc,note]=row;return `<label class="task${checked[id]===true?' completed':''}"><input type="checkbox" id="${esc(id)}" data-extra="${extra}" ${checked[id]===true?'checked':''}><span class="checkmark" aria-hidden="true"></span><span class="task-copy"><span class="task-title">${esc(title)}</span> <span class="specialty">(${esc(desc)})</span>${note?`<span class="task-note">${esc(note)}</span>`:''}</span></label>`;}
const PHOTOS={"centro": [[["/assets/oax-alcala.jpeg", "Colourful colonial houses along the Andador Macedonio Alcalá", 1400, 1400, "Zitenshi", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Macedonio_de_Alcal%C3%A1.jpg"], ["/assets/oax-jardin.jpeg", "Tall organ-pipe cacti in the Jardín Etnobotánico beside the old convent", 1400, 1050, "Kaldari", "CC0", "https://commons.wikimedia.org/wiki/File:Jard%C3%ADn_Etnobot%C3%A1nico_de_Oaxaca_06.JPG"]], [["/assets/oax-tlayuda.jpeg", "A tlayuda topped with meat, avocado and grilled spring onions", 1400, 1050, "Gomez.erick", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:TLAYUDA.jpg"], ["/assets/oax-chocolate.jpeg", "Cacao being ground in the molinos at a Mayordomo chocolate shop", 930, 1400, "LBM1948", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Oaxaca_de_Ju%C3%A1rez,_23.jpg"]]], "muertos": [[["/assets/oax-altar.jpeg", "A Día de Muertos altar heaped with marigolds, candles, fruit and photos", 1400, 1050, "Jmillan325", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Altar_de_D%C3%ADa_de_Muertos_en_el_Tule_Oaxaca.jpg"], ["/assets/oax-comparsa.jpeg", "Costumed dancers with bells on their legs in a Día de Muertos comparsa", 933, 1400, "David Cabrera", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Cascabeles.jpg"]], [["/assets/oax-xoxo.jpeg", "Families keeping vigil among candlelit graves at the Xoxocotlán cemetery", 1400, 933, "Pedro Daniel Godínez Corona", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Velando_en_el_Pante%C3%B3n_de_Xoxocotl%C3%A1n.jpg"]]], "markets": [[["/assets/oax-mercado.jpeg", "Grill smoke drifting through the meat aisle of Mercado 20 de Noviembre", 1400, 937, "ProtoplasmaKid", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Mercado_20_de_noviembre_-_Oaxaca_de_Ju%C3%A1rez_-_10.jpg"]], []], "cooking": [[["/assets/oax-mole.jpeg", "A plate of mole negro with rice", 1400, 1050, "ProtoplasmaKid", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Mole_negro_de_Oaxaca_con_arroz.jpg"]]], "montealban": [[["/assets/oax-montealban.jpeg", "The Gran Plaza of Monte Albán on its flattened hilltop above the valley", 1400, 1060, "Infrogmation", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Monte_Alb%C3%A1n_Oaxaca_1976_01.jpg"]]], "hierve": [[["/assets/oax-hierve.jpeg", "The white, petrified waterfall of Hierve el Agua spilling down a green mountainside", 1400, 1050, "Adrián Cerón", "CC BY-SA 3.0", "https://commons.wikimedia.org/wiki/File:Hierve_el_agua.JPG"], ["/assets/oax-mitla.jpeg", "Stone fretwork walls around a courtyard at Mitla", 1400, 933, "DavidConFran", "CC BY-SA 3.0", "https://commons.wikimedia.org/wiki/File:Patio_Grupo_Norte.JPG"]]], "tlacolula": [[["/assets/oax-tlacolula.jpeg", "Stalls of fruit, flowers and bread at the Tlacolula Sunday market", 1400, 933, "Bluerasberry", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Tlacolula_Market_230122_62.jpg"], ["/assets/oax-teotitlan.jpeg", "A weaver at a wooden loom in Teotitlán del Valle, with finished rugs behind", 1280, 854, "Axel Alvarado Chávez", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Tejido_de_Tapetes_Artesanales_en_Telar._Teotitl%C3%A1n_Del_Valle,_Oaxaca.jpg"]]], "food": [[], [["/assets/oax-fire.jpeg", "A woman stirring a big pot of mole over a wood fire", 1050, 1400, "Diego Emiliano Jaramillo Navarro", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Do%C3%B1a_Mari,_la_Reina_del_Mole.jpg"], ["/assets/oax-tlayuda-grill.jpeg", "A tlayuda vendor at a street grill in Oaxaca at night", 787, 1400, "Alex Haulman", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Tlayuda_vendor_in_Oaxaca_City.jpg"]], []]};
const fig=([src,alt,w,h,by,lic,url])=>`<figure class="fn-v-photo"><a href="${src}" target="_blank" rel="noopener"><img src="${src}" alt="${esc(alt)}" width="${w}" height="${h}" loading="lazy"></a>${by?`<figcaption>Photo: ${by} · <a href="${url}" target="_blank" rel="noopener noreferrer">${lic}</a></figcaption>`:''}</figure>`;
let rowN=0;
document.querySelector('#itinerary').innerHTML=groups.map(g=>`<section id="${g.id}" class="outing fn-split ${g.color} ${g.weekend?'weekend':''}" aria-labelledby="title-${g.id}"><div class="outing-heading"><span class="number" aria-hidden="true">${g.number}</span><div><p class="eyebrow">${g.timing}</p><h2 id="title-${g.id}">${g.title}</h2><p class="section-desc">${g.description}</p></div><span class="group-count" id="count-${g.id}" aria-label="Section completion"></span></div><div class="outing-body fn-split-body">${g.sections.map(([title,rows],si)=>{const ps=(PHOTOS[g.id]||[])[si]||[];const card=`<div class="task-group"><h3>${title}</h3>${rows.map(r=>item(r)).join('')}</div>`;return ps.length?`<div class="fn-v-row${rowN++%2?' fn-v-rev':''}"><div class="fn-v-side">${ps.map(fig).join('')}</div>${card}</div>`:card;}).join('')}</div><div class="outing-note"><p>${g.note}</p>${g.link?`<a href="${g.link[1]}" target="_blank" rel="noopener noreferrer">${g.link[0]} ↗︎</a>`:''}</div></section>`).join('');
document.querySelector('#optional-list').innerHTML=optional.map(r=>item(r,true)).join('');
const mainIds=groups.flatMap(g=>g.sections.flatMap(s=>s[1].map(r=>r[0])));
function update(announce=false){const done=mainIds.filter(id=>checked[id]===true).length;const percent=Math.round(done/mainIds.length*100);document.querySelector('#progress-count').textContent=done;document.querySelector('#progress-total').textContent=`of ${mainIds.length} places & moments`;document.querySelector('#percent').textContent=percent+'%';document.querySelector('#progress').value=percent;document.querySelector('#progress').textContent=percent+'%';groups.forEach(g=>{const ids=g.sections.flatMap(s=>s[1].map(r=>r[0]));document.querySelector('#count-'+g.id).textContent=`${ids.filter(id=>checked[id]===true).length} / ${ids.length}`;});const extra=optional.filter(r=>checked[r[0]]===true).length;document.querySelector('#extra-count').textContent=`${extra} optional ${extra===1?'stop':'stops'} done`;document.querySelector('#save-note').textContent=storageOK?'Progress saved on this device.':'Progress works here, but saving is unavailable in this browser.';if(announce)document.querySelector('#announcement').textContent=`${done} of ${mainIds.length} main items complete. ${extra} optional stops done.`;}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(checked));storageOK=true;}catch{storageOK=false;}}
document.addEventListener('change',e=>{if(!e.target.matches('.task input'))return;checked[e.target.id]=e.target.checked;e.target.closest('.task').classList.toggle('completed',e.target.checked);persist();update(true);});
window.addEventListener('storage',e=>{if(e.key!==KEY)return;try{const next=JSON.parse(e.newValue||'{}');checked=next&&typeof next==='object'&&!Array.isArray(next)?next:{};}catch{checked={};}document.querySelectorAll('.task input').forEach(el=>{el.checked=checked[el.id]===true;el.closest('.task').classList.toggle('completed',el.checked);});update();});
const dialog=document.querySelector('#reset-dialog');document.querySelector('#reset').addEventListener('click',()=>dialog.showModal());document.querySelector('#cancel-reset').addEventListener('click',()=>dialog.close());document.querySelector('#confirm-reset').addEventListener('click',()=>{checked={};persist();document.querySelectorAll('.task input').forEach(el=>{el.checked=false;el.closest('.task').classList.remove('completed');});update(true);dialog.close();});
update();
